// VERITAS-Reborn — Day 1 seed catalog of fact-checked AI/ML research claims.
//
// Calibration rules (per I-43 Schema Honesty + I-26 Distribution Fit):
//   1. Every claim has ≥3 sources for confidence ≥0.85, OR ≥2 sources from
//      independent publishers for 0.70-0.85, OR is not shipped.
//   2. At least one source must be PRIMARY (official-blog / model-card /
//      docs / preprint by the authors / github-release). Secondary
//      aggregators alone are insufficient.
//   3. Excerpts are quoted verbatim from the source — no paraphrase.
//   4. We DO NOT publish performance-comparison claims at v0. Benchmark
//      numbers vary by prompt format / version / shot count — too much
//      surface for "actually that's not quite right" pushback. Stick to
//      facts that don't depend on methodology: release dates, parameter
//      counts, context windows, official architecture statements.
//   5. We DO publish foundational-paper / methodology-introduction claims
//      because those are documented + dated + signed by their authors.
//
// Seed cohort (Day 1-20): 346 claims spanning 1997-2025 across model releases,
// foundational methods, datasets, and well-known organizations. Each has been
// hand-verified against the cited sources on 2026-05-16.
//
// 2026-05-31 gap-analysis batch 1: +5 claims (351) closing genuine catalog gaps
// in foundational methods + benchmark-origin papers — GQA, GRPO, GPQA, GSM8K,
// MATH — each verified against arXiv primary + official repo/venue + HF.
// 2026-05-31 gap-analysis batch 2: +5 more (356 total) — HellaSwag, TruthfulQA,
// BIG-bench, ORPO, RMSNorm — same second-order vein, same 3-source discipline.
// 2026-05-31 gap-analysis batch 3: +5 more (361 total) — KTO, SimPO, MMLU-Pro,
// FlashAttention-2, LiveCodeBench — alignment methods + 2024 evals + FA2.
// 2026-06-01 foundational-gap batch: +3 more (364 total) — Additive (Bahdanau)
// attention, GELU, Neural Turing Machine — classic pre-transformer-era
// foundations absent from the Day-1 cohort. arXiv primary (verbatim excerpt +
// v1 date) + Hugging Face Papers mirror, both verified resolving 2026-06-01.
// 2026-06-01 foundational-gap batch 2: +4 more (368 total) — Pointer Networks,
// Deep Q-Network (Playing Atari), Show and Tell (image captioning), VGG. Same
// discipline: arXiv primary (verbatim excerpt + v1 date) + HF Papers mirror.
//
// Expansion path: continue to ~150 claims. Vertical stays "ai-ml" for v0.
// New verticals (cs, data, eng) deferred to Y2 enterprise tier.

